mapper.select:
select count(*) from dish_templates t
left join dishes d on d.source_template_id=t.id and d.merchant_id = #{merchantId}
where

select  from dish_templates t
join dish_template_categories c on c.id=t.category_id and c.enabled=1
left join dishes d on d.source_template_id=t.id and d.merchant_id = #{merchantId}
where 
order by c.sort_order,t.sort_order,t.id limit #{offset},#{pageSize}

select  from dish_templates t
join dish_template_categories c on c.id=t.category_id left join dishes d on 1=0
where t.id=#{templateId}

mapper.update:
update dish_template_image_assets set asset_status=#{assetStatus},public_image_url=#{publicImageUrl},
  image_author=#{imageAuthor},image_license=#{imageLicense},reviewed_by=#{reviewedBy},
  reviewed_at=#{reviewedAt},rejection_reason=#{rejectionReason}
where id=#{id} and template_id=#{templateId}

update dish_templates set image_url=#{publicImageUrl},image_source_url=#{sourceUrl},
  image_author=#{author},image_license=#{license},image_rights_status='DECLARED',version=version+1
where id=#{templateId} and version=#{expectedVersion}

update dish_template_image_assets set asset_status='REJECTED',reviewed_by=#{reviewedBy},
  reviewed_at=current_timestamp,rejection_reason=#{reason}
where id=#{assetId} and asset_status='INTERNAL_REVIEW'
